const helpers=[['Jelaskan sederhana','Jelaskan topik berikut dengan bahasa sederhana untuk siswa SMP, beri contoh: '],['Ringkas teks','Ringkas teks berikut menjadi poin utama: '],['Latihan soal','Buat latihan soal topik berikut dengan kunci jawaban di akhir: '],['Rencana esai','Bantu membuat kerangka esai dan pembuka tentang: '],['Perbaiki tata bahasa','Perbaiki tata bahasa teks berikut dan jelaskan perubahan: '],['Terjemahkan','Terjemahkan teks berikut, jelaskan kata kunci dan tanyakan bahasa tujuan jika belum disebutkan: '],['Jelajah kata','Jelaskan arti, sinonim, dan contoh kalimat kata berikut: '],['Periksa PR','Periksa pekerjaanku, beri petunjuk dan jelaskan kesalahan tanpa langsung menyelesaikan semuanya: '],['Catatan revisi','Buat catatan belajar terstruktur dan teknik mengingat untuk topik: ']];
const styles={auto:'',steps:'Jelaskan dengan langkah bernomor. Tunjukkan cara dan alasan setiap langkah.',hints:'Berikan petunjuk dan pertanyaan pemandu. Jangan berikan jawaban akhir sebelum siswa mencoba.',short:'Jawab ringkas dalam 3–4 kalimat, kecuali pengguna meminta format lain.',quiz:'Ajukan satu pertanyaan latihan saja. Tunggu jawaban pengguna, beri umpan balik, lalu lanjutkan.',check:'Periksa pekerjaan pengguna. Tunjukkan kesalahan, koreksi, dan alasan. Jika pekerjaannya belum ada, minta terlebih dahulu.'};
window.studyAnswerInstruction=()=>styles[state.style]?'\n\nGaya belajar yang dipilih: '+styles[state.style]:'';
