const library=document.createElement('dialog');library.className='study-library';library.setAttribute('aria-labelledby','studyLibraryTitle');library.innerHTML='<div class="study-heading"><h2 id="studyLibraryTitle">Pusat alat belajar</h2><button class="study-button" data-close-library aria-label="Tutup alat belajar">Tutup</button></div><p>Buka alat di samping percakapan. Catatan, tugas, dan flashcard disimpan di perangkat ini untuk akunmu.</p>'+['Sains','Matematika','Belajar'].map(group=>'<h3 class="study-section-title">'+group+'</h3><div class="study-grid">'+tools.filter(t=>t[4]===group).map(t=>`<button class="study-tile" data-tool="${t[0]}"><i data-icon="${t[3]}"></i><strong>${t[1]}</strong><span>${t[2]}</span></button>`).join('')+'</div>').join('')+'<h3 class="study-section-title">Bantuan AI</h3><div class="study-helper-grid">'+helpers.map((h,i)=>`<button class="study-button" data-helper="${i}">${h[0]}</button>`).join('')+'</div>';
document.body.append(library);library.onclick=e=>{const t=e.target.closest('[data-tool]'),h=e.target.closest('[data-helper]');if(t){library.close();open(t.dataset.tool);}if(h){library.close();draft(helpers[+h.dataset.helper][1]);}if(e.target.closest('[data-close-library]'))library.close();};
const panel=document.createElement('aside');panel.className='study-panel';panel.setAttribute('aria-label','Panel alat & fitur');panel.innerHTML='<header class="study-panel-head"><div><strong id="studyToolTitle"></strong><small id="studyToolCaption"></small></div><div class="study-toolbar-actions"><button class="study-button" data-library title="Semua alat" aria-label="Semua alat"><i data-icon="grid-2x2"></i></button><button class="study-button" data-wide title="Perluas panel" aria-label="Perluas panel"><i data-icon="maximize"></i></button><button class="study-button" data-close title="Tutup alat" aria-label="Tutup alat"><i data-icon="x"></i></button></div></header><div class="study-panel-body" id="studyBody"></div>';
$s('.app-shell').append(panel);hydrateIcons(panel);const body=$s('#studyBody');let current='',cleanup=()=>{},origin=null;
function showLibrary(){library.showModal();hydrateIcons(library);}
$s('#studyLaunch').onclick=showLibrary;$s('#studyTopLaunch').onclick=showLibrary;
panel.querySelector('[data-library]').onclick=showLibrary;
panel.querySelector('[data-close]').onclick=()=>{cleanup();panel.classList.remove('open','wide');$s('#studyTopLaunch').focus();};
panel.querySelector('[data-wide]').onclick=()=>{panel.classList.toggle('wide');requestAnimationFrame(()=>window.dispatchEvent(new Event('resize')));};
panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();panel.querySelector('[data-close]').click();}});
window.openStudyTool=id=>open(id);window.openStudyLibrary=()=>showLibrary();
function open(id){const tool=tools.find(t=>t[0]===id);if(!tool)return;cleanup();cleanup=()=>{};origin=document.activeElement;current=id;panel.classList.add('open');$s('#studyToolTitle').textContent=tool[1];$s('#studyToolCaption').textContent=tool[2];body.innerHTML='';renderers[id]();hydrateIcons(body);window.dispatchEvent(new CustomEvent('study-tool-open',{detail:{id}}));panel.querySelector('[data-close]').focus();if(innerWidth<760)closeSidebar();}
function draft(text){els.input.value=text;autoResize();if(innerWidth<760)panel.classList.remove('open');closeSidebar();els.input.focus();}
function ask(text){draft(text);showToast('Lengkapi atau periksa pesan, lalu kirim ke AI.');}
function button(text,id,primary=false){return `<button class="study-button${primary?' primary':''}" id="${id}" type="button">${text}</button>`;}
function input(label,id,value='',type='text'){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}">`;}
function out(id='studyResult'){return `<div class="study-output" id="${id}" role="status" aria-live="polite"></div>`;}
function val(id){return body.querySelector('#'+id).value;}
function on(id,fn,event='click'){body.querySelector('#'+id).addEventListener(event,fn);}
window.openStudyFromPrompt=text=>{const match=String(text||'').trim().match(/^(?:buka|open|tampilkan|show)(?:\s+(?:the|me|saya))?\s+(kalkulator|calculator|tabel periodik|periodic table|laboratorium virtual|virtual lab|tata surya|solar system|grafik fungsi|graph plotter|konversi satuan|unit converter|flashcards?|timer fokus|focus timer|agenda tugas|homework planner|catatan|notes|rumus|formulas)\s*[.!]?$/i);if(!match)return false;const names={'kalkulator':'calculator','calculator':'calculator','tabel periodik':'periodic','periodic table':'periodic','laboratorium virtual':'lab','virtual lab':'lab','tata surya':'solar','solar system':'solar','grafik fungsi':'graph','graph plotter':'graph','konversi satuan':'convert','unit converter':'convert','flashcard':'cards','flashcards':'cards','timer fokus':'timer','focus timer':'timer','agenda tugas':'planner','homework planner':'planner','catatan':'notes','notes':'notes','rumus':'formulas','formulas':'formulas'};open(names[match[1].toLowerCase()]);els.input.value='';autoResize();return true;};
/* A small expression parser. No eval, Function, or JavaScript execution. */
function calculate(source,x=0,degrees=false){
 const sourceClean=String(source).replace(/π/g,'pi').replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/\s+/g,'');
 const tokens=sourceClean.match(/(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|[a-z]+|[()+\-*/^%,]/g)||[];
 if(tokens.join('')!==sourceClean||tokens.length>250)throw Error('Ekspresi tidak valid.');let p=0,depth=0;
 const fns={sin:v=>Math.sin(degrees?v*Math.PI/180:v),cos:v=>Math.cos(degrees?v*Math.PI/180:v),tan:v=>Math.tan(degrees?v*Math.PI/180:v),sqrt:Math.sqrt,abs:Math.abs,ln:Math.log,log:Math.log10,exp:Math.exp,floor:Math.floor,ceil:Math.ceil};
 function atom(){if(++depth>50)throw Error('Ekspresi terlalu dalam.');let n,t=tokens[p++];if(t==='+'||t==='-')n=(t==='-'?-1:1)*expr(3);else if(t==='('){n=expr(0);if(tokens[p++]!==')')throw Error('Kurung belum lengkap.');}else if(t==='x')n=x;else if(t==='pi')n=Math.PI;else if(t==='e')n=Math.E;else if(Object.hasOwn(fns,t)){if(tokens[p++]!=='(')throw Error('Fungsi memakai tanda kurung.');n=fns[t](expr(0));if(tokens[p++]!==')')throw Error('Kurung belum lengkap.');}else if(t&&/^(\d|\.)/.test(t))n=Number(t);else throw Error('Angka atau fungsi tidak dikenal.');depth--;return n;}
 function expr(min){let n=atom();while(p<tokens.length){const op=tokens[p],prec={'+':1,'-':1,'*':2,'/':2,'%':2,'^':3}[op];if(!prec||prec<min)break;p++;const r=expr(op==='^'?prec:prec+1);n=op==='+'?n+r:op==='-'?n-r:op==='*'?n*r:op==='/'?n/r:op==='%'?n%r:Math.pow(n,r);}return n;}
 const result=expr(0);if(p!==tokens.length||!Number.isFinite(result))throw Error('Hasil tidak terdefinisi. Periksa domain dan pembagian nol.');return result;
}
const fmt=n=>Number(n.toPrecision(10)).toLocaleString('id-ID',{maximumFractionDigits:10});
const renderers={};
window.registerWorkspaceTool=(spec,renderer)=>{if(!tools.some(t=>t[0]===spec[0]))tools.push(spec);renderers[spec[0]]=renderer;};
renderers.calculator=()=>{body.innerHTML=input('Ekspresi','calc','sin(30) + 2^3')+'<div class="study-row"><label><input type="checkbox" id="degrees" checked> Sudut dalam derajat</label>'+button('Hitung','equals',true)+'</div>'+out()+'<div class="study-keypad">'+['7','8','9','(',')','4','5','6','+','-','1','2','3','*','/','0','.','pi','^','sqrt(','sin(','cos(','tan(','log(','ln('].map(v=>`<button class="study-button" data-key="${v}">${v}</button>`).join('')+'</div><div class="study-row">'+button('Hapus','clearCalc')+button('Jelaskan dengan AI','calcAsk')+'</div><p class="study-muted">Gunakan perkalian eksplisit, misalnya 2*x. log berbasis 10, ln berbasis e.</p>';function run(){try{$s('#studyResult').textContent=fmt(calculate(val('calc'),0,$s('#degrees').checked));}catch(e){$s('#studyResult').textContent=e.message;}}on('equals',run);on('calc',e=>{if(e.key==='Enter')run();},'keydown');body.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const i=$s('#calc');i.setRangeText(b.dataset.key,i.selectionStart,i.selectionEnd,'end');i.focus();});on('clearCalc',()=>{$s('#calc').value='';});on('calcAsk',()=>ask('Jelaskan cara menghitung '+val('calc')));run();};
const units={Panjang:{m:1,km:1000,cm:.01,mm:.001,in:.0254,ft:.3048,yd:.9144,mi:1609.344},Massa:{kg:1,g:.001,mg:.000001,tonne:1000,lb:.45359237,oz:.028349523125},Waktu:{s:1,min:60,h:3600,hari:86400,minggu:604800},Suhu:{'°C':'c','°F':'f',K:'k'},Luas:{'m²':1,'cm²':.0001,'km²':1e6,ha:1e4,'ft²':.09290304,acre:4046.8564224},Volume:{L:1,mL:.001,'m³':1000,'cm³':.001,'US gal':3.785411784},Kecepatan:{'m/s':1,'km/h':1/3.6,mph:.44704,knot:.514444444},Tekanan:{Pa:1,kPa:1000,bar:100000,atm:101325,psi:6894.757293},Energi:{J:1,kJ:1000,cal:4.184,kcal:4184,Wh:3600,kWh:3600000},Daya:{W:1,kW:1000,MW:1e6,hp:745.6998716}};
function convertValue(n,category,from,to){const u=units[category];if(category==='Suhu'){const c=from==='°C'?n:from==='°F'?(n-32)*5/9:n-273.15;return to==='°C'?c:to==='°F'?c*9/5+32:c+273.15;}return n*u[from]/u[to];}
renderers.convert=()=>{body.innerHTML='<label for="unitCategory">Kategori</label><select id="unitCategory">'+Object.keys(units).map(k=>`<option>${k}</option>`).join('')+'</select>'+input('Nilai','unitValue','1','number')+'<div class="study-row"><div><label for="unitFrom">Dari</label><select id="unitFrom"></select></div><div><label for="unitTo">Ke</label><select id="unitTo"></select></div></div>'+out();const run=()=>{const n=Number(val('unitValue'));$s('#studyResult').textContent=val('unitValue')!==''&&Number.isFinite(n)?fmt(convertValue(n,val('unitCategory'),val('unitFrom'),val('unitTo')))+' '+val('unitTo'):'Masukkan angka.';};function options(){const html=Object.keys(units[val('unitCategory')]).map(k=>`<option>${k}</option>`).join('');$s('#unitFrom').innerHTML=html;$s('#unitTo').innerHTML=html;$s('#unitTo').selectedIndex=1;run();}on('unitCategory',options,'change');['unitValue','unitFrom','unitTo'].forEach(id=>on(id,run,'input'));options();};
renderers.graph=()=>{body.innerHTML='<p class="study-muted">Gunakan x, + − * / ^, sin, cos, tan, sqrt, log, ln. Trigonometri dalam radian.</p>'+[0,1,2].map((_,i)=>input('Fungsi '+(i+1),'graph'+i,['x^2','sin(x)',''][i])).join('')+'<div class="study-row">'+button('Gambar','plot',true)+button('Reset tampilan','resetGraph')+'</div><canvas id="graphCanvas" aria-label="Grafik fungsi. Geser untuk memindahkan, gulir untuk zoom."></canvas><div class="study-row">'+button('Perbesar','zoomIn')+button('Perkecil','zoomOut')+'</div>'+out()+'<p class="study-muted">Biru: fungsi 1 · ungu: fungsi 2 · hijau: fungsi 3. Geser grafik untuk memindahkan pusat.</p>';const canvas=$s('#graphCanvas');let cx=0,cy=0,scale=30,drag=null;
 function draw(){const r=canvas.getBoundingClientRect(),w=r.width,h=300,dpr=devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.clearRect(0,0,w,h);c.lineWidth=1;const step=10**Math.floor(Math.log10(75/scale));c.font='11px system-ui';c.fillStyle='#a9b8d0';c.strokeStyle='#1d2a40';for(let x=Math.floor((cx-w/2/scale)/step)*step;x<cx+w/2/scale;x+=step){const px=w/2+(x-cx)*scale;c.beginPath();c.moveTo(px,0);c.lineTo(px,h);c.stroke();c.fillText(Number(x.toPrecision(4)),px+3,Math.max(12,Math.min(h-5,h/2+cy*scale+14)));}for(let y=Math.floor((cy-h/2/scale)/step)*step;y<cy+h/2/scale;y+=step){const py=h/2-(y-cy)*scale;c.beginPath();c.moveTo(0,py);c.lineTo(w,py);c.stroke();}c.strokeStyle='#65758e';c.beginPath();c.moveTo(w/2-cx*scale,0);c.lineTo(w/2-cx*scale,h);c.moveTo(0,h/2+cy*scale);c.lineTo(w,h/2+cy*scale);c.stroke();let errors=[];['#6d9eff','#b79bff','#50dab3'].forEach((color,i)=>{const f=val('graph'+i).trim();if(!f)return;c.strokeStyle=color;c.lineWidth=2;c.beginPath();let previous=null;for(let px=0;px<=w;px+=1){try{const y=calculate(f,cx+(px-w/2)/scale),py=h/2-(y-cy)*scale;if(Math.abs(py)>h*20){previous=null;continue;}if(previous===null||Math.abs(py-previous)>h)c.moveTo(px,py);else c.lineTo(px,py);previous=py;}catch(e){previous=null;if(!errors.includes(i+1))errors.push(i+1);}}c.stroke();});$s('#studyResult').textContent=errors.length?'Fungsi '+errors.join(', ')+': sebagian titik di luar domain atau ekspresi tidak valid.':'Pusat ('+fmt(cx)+', '+fmt(cy)+').';}
 on('plot',draw);on('resetGraph',()=>{cx=cy=0;scale=30;draw();});on('zoomIn',()=>{scale=Math.min(500,scale*1.3);draw();});on('zoomOut',()=>{scale=Math.max(2,scale/1.3);draw();});canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY,cx,cy];canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){cx=drag[2]-(e.clientX-drag[0])/scale;cy=drag[3]+(e.clientY-drag[1])/scale;draw();}};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(2,Math.min(500,scale*Math.exp(-e.deltaY*.002)));draw();},{passive:false});const observer=new ResizeObserver(draw);observer.observe(canvas);cleanup=()=>observer.disconnect();requestAnimationFrame(draw);};
const masses={H:1.008,He:4.0026,Li:6.94,Be:9.0122,B:10.81,C:12.011,N:14.007,O:15.999,F:18.998,Ne:20.18,Na:22.99,Mg:24.305,Al:26.982,Si:28.085,P:30.974,S:32.06,Cl:35.45,Ar:39.948,K:39.098,Ca:40.078,Fe:55.845,Cu:63.546,Zn:65.38,Ag:107.868,Br:79.904,I:126.904,Ba:137.327,Au:196.967,Pb:207.2};
function molarMass(formula){const raw=formula.replace(/\s+/g,'');const ts=raw.match(/[A-Z][a-z]?|\d+|[()]/g)||[];if(ts.join('')!==raw||!ts.length||ts.length>150)throw Error('Gunakan formula netral seperti H2O atau Ca(OH)2.');let i=0,depth=0;function group(nested=false){if(++depth>20)throw Error('Formula terlalu panjang.');let total=0,count=0;while(i<ts.length&&ts[i]!==')'){let value;if(ts[i]==='('){i++;value=group(true);}else{const symbol=ts[i++];if(!Object.hasOwn(masses,symbol))throw Error('Massa unsur '+symbol+' belum tersedia pada kalkulator ini.');value=masses[symbol];}let n=/^\d+$/.test(ts[i]||'')?Number(ts[i++]):1;if(n<1||n>10000)throw Error('Indeks atom tidak valid.');total+=value*n;count++;}if(nested&&ts[i++]!==')')throw Error('Kurung belum lengkap.');if(!count)throw Error('Formula kosong.');depth--;return total;}const result=group();if(i!==ts.length)throw Error('Kurung tidak seimbang.');return result;}
renderers.periodic=()=>{body.innerHTML=renderPeriodicTable('{}')+'<section class="study-card"><h3>Massa molar</h3>'+input('Formula kimia netral','molar','Ca(OH)2')+button('Hitung massa molar','massCalc',true)+out()+'<p class="study-muted">Satuan g/mol. Nilai massa atom dibulatkan; formula dapat memakai tanda kurung. Unsur yang belum didukung akan ditandai.</p></section>';bindVisualInteractions();body.querySelectorAll('.periodic-element').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.number),detail=body.querySelector('.element-detail>div');if(n<=20){const shells=[];let left=n;for(const max of [2,8,8,2]){if(left<=0)break;shells.push(Math.min(max,left));left-=Math.min(max,left);}const p=document.createElement('p');p.textContent='Elektron per kulit (atom netral): '+shells.join(' · ');detail.append(p);}if(masses[b.dataset.element]){const p=document.createElement('p');p.textContent='Massa atom relatif (dibulatkan): '+masses[b.dataset.element];detail.append(p);}}));on('massCalc',()=>{try{$s('#studyResult').textContent=fmt(molarMass(val('molar')))+' g/mol';}catch(e){$s('#studyResult').textContent=e.message;}});$s('#massCalc').click();};
const planets=[['Merkurius',.387,.241,'#b4aaa1','Planet berbatu terdekat dari Matahari.'],['Venus',.723,.615,'#eac281','Planet berbatu dengan atmosfer tebal.'],['Bumi',1,1,'#5b9dff','Planet berbatu dengan air cair di permukaan.'],['Mars',1.524,1.881,'#da7960','Planet berbatu dengan permukaan kemerahan.'],['Jupiter',5.203,11.86,'#d2b08b','Planet raksasa gas terbesar.'],['Saturnus',9.537,29.46,'#e0c882','Raksasa gas dengan sistem cincin yang jelas.'],['Uranus',19.19,84.01,'#89d6df','Raksasa es yang berotasi dengan sumbu sangat miring.'],['Neptunus',30.07,164.8,'#6184ff','Raksasa es terjauh dari Matahari.']];
renderers.solar=()=>{body.innerHTML='<canvas id="solarCanvas" aria-label="Diagram orbit delapan planet"></canvas><p class="study-muted">Diagram untuk belajar. Ukuran planet dan jarak pada gambar tidak berskala. Periode orbit dalam tahun Bumi, jarak rata-rata dalam AU.</p><div class="study-solar-list">'+planets.map((p,i)=>`<button class="study-button" data-planet="${i}"><span class="planet-dot" style="background:${p[3]}"></span>${p[0]}</button>`).join('')+'</div>'+out()+'<p class="study-muted">Sumber: <a href="https://science.nasa.gov/learn/basics-of-space-flight/chapter1-2/" target="_blank" rel="noopener">NASA Solar System</a></p>';let selected=2;const canvas=$s('#solarCanvas');function render(){const p=planets[selected];$s('#studyResult').innerHTML='<strong>'+p[0]+'</strong><p>'+p[4]+'</p><p>Jarak: '+p[1]+' AU · Periode orbit: '+p[2]+' tahun Bumi.</p>'+button('Pelajari dengan AI','planetAsk');window.dispatchEvent(new CustomEvent('solar-planet-change',{detail:{index:selected}}));on('planetAsk',()=>ask('Jelaskan planet '+p[0]+' untuk siswa SMP dan bandingkan dengan Bumi.'));const w=canvas.clientWidth,h=300,dpr=devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.translate(w/2,h/2);c.fillStyle='#ffd077';c.beginPath();c.arc(0,0,12,0,Math.PI*2);c.fill();planets.forEach((pl,i)=>{const rad=22+i*14;c.strokeStyle='#24324c';c.beginPath();c.ellipse(0,0,rad,rad*.7,0,0,Math.PI*2);c.stroke();const a=i*.82;c.fillStyle=pl[3];c.beginPath();c.arc(Math.cos(a)*rad,Math.sin(a)*rad*.7,i===selected?7:4,0,Math.PI*2);c.fill();});}body.querySelectorAll('[data-planet]').forEach(b=>b.onclick=()=>{selected=+b.dataset.planet;render();});const ob=new ResizeObserver(render);ob.observe(canvas);cleanup=()=>ob.disconnect();render();};
renderers.lab=()=>{const experiments=[['ph','pH & indikator'],['pendulum','Bandul'],['circuit','Rangkaian'],['density','Massa jenis'],['particles','Partikel']];body.innerHTML='<div class="study-tabs" role="tablist" aria-label="Eksperimen">'+experiments.map(([id,name])=>`<button class="study-button" role="tab" data-experiment="${id}" aria-selected="false">${name}</button>`).join('')+'</div><div id="labExperiment"></div><p class="study-live-note">Simulasi memakai model sederhana untuk memahami konsep. Hasilnya bukan petunjuk eksperimen dengan bahan berbahaya.</p>';let labCleanup=()=>{};
function select(id){labCleanup();labCleanup=()=>{};body.querySelectorAll('[data-experiment]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.experiment===id)));const target=$s('#labExperiment');
 if(id==='ph'){const liquids=[['Air murni',7],['Air lemon',2.2],['Cuka',3],['Kopi',5],['Susu',6.5],['Larutan soda kue',8.3],['Air sabun',10]];target.innerHTML='<h3>Asam, basa, dan indikator</h3><p class="study-muted">Pilih larutan dan indikator. Nilai pH contoh bersifat perkiraan dan dapat berbeda menurut konsentrasi.</p><label for="liquid">Larutan</label><select id="liquid">'+liquids.map((l,i)=>`<option value="${i}">${l[0]}</option>`).join('')+'</select><label for="indicator">Indikator</label><select id="indicator"><option>Universal</option><option>Lakmus</option><option>Fenolftalein</option><option>Metil jingga</option><option>Kol ungu</option></select><div class="study-lab-visual"><div id="beaker" class="study-beaker"></div></div>'+out();function update(){const [name,ph]=liquids[+val('liquid')],ind=val('indicator');let color=ph<3?'#f46b71':ph<6?'#efa658':ph===7?'#79d79a':ph<10?'#6aafd9':'#a582df';if(ind==='Lakmus')color=ph<7?'#ed777e':ph>7?'#7d9af4':'#ac85cb';if(ind==='Fenolftalein')color=ph<8.2?'#dceef599':'#ee74b8';if(ind==='Metil jingga')color=ph<3.1?'#f56b70':ph>4.4?'#e9d55d':'#eda553';if(ind==='Kol ungu')color=ph<7?'#df82ae':ph===7?'#a48ada':'#76c7a6';$s('#beaker').style.background=color;$s('#beaker').textContent='pH '+ph;$s('#studyResult').textContent=name+': '+(ph<7?'asam':ph>7?'basa':'netral')+'. Indikator '+ind+'. Semakin jauh dari pH 7, semakin asam atau basa pada skala pH.';}on('liquid',update,'change');on('indicator',update,'change');update();}
 if(id==='pendulum'){target.innerHTML='<h3>Bandul sederhana</h3><p class="study-muted">Model sudut kecil tanpa gesekan. Ubah panjang tali dan gravitasi; massa tidak memengaruhi periode pada model ini.</p><label>Panjang tali: <span id="lengthValue"></span> m</label><input id="length" class="study-slider" type="range" min="0.2" max="3" value="1" step="0.1"><label for="gravity">Gravitasi</label><select id="gravity"><option value="9.81">Bumi (9,81 m/s²)</option><option value="1.62">Bulan (1,62 m/s²)</option><option value="3.71">Mars (3,71 m/s²)</option></select><canvas id="pendulumCanvas" aria-label="Bandul berayun"></canvas>'+out();const canvas=$s('#pendulumCanvas'),started=performance.now();let frame;function draw(){if(canvas.hidden)return;const length=Number(val('length')),g=Number(val('gravity')),T=2*Math.PI*Math.sqrt(length/g);$s('#lengthValue').textContent=length;$s('#studyResult').textContent='T = 2π√(L/g) = '+T.toFixed(2)+' detik per ayunan penuh.';const w=canvas.clientWidth;canvas.width=w;canvas.height=300;const c=canvas.getContext('2d'),a=matchMedia('(prefers-reduced-motion: reduce)').matches?.15:.2*Math.cos((performance.now()-started)/1000*2*Math.PI/T),r=80+length*35,x=w/2+Math.sin(a)*r,y=20+Math.cos(a)*r;c.strokeStyle='#98abc7';c.lineWidth=3;c.beginPath();c.moveTo(w/2,20);c.lineTo(x,y);c.stroke();c.fillStyle='#739bff';c.beginPath();c.arc(x,y,14,0,Math.PI*2);c.fill();frame=requestAnimationFrame(draw);}draw();labCleanup=()=>cancelAnimationFrame(frame);}
 if(id==='circuit'){target.innerHTML='<h3>Hukum Ohm</h3><p class="study-muted">Baterai ideal dan satu resistor. Ubah tegangan serta hambatan.</p>'+input('Tegangan (V)','voltage','6','number')+input('Hambatan (Ω)','resistance','10','number')+'<label><input type="checkbox" id="closedCircuit" checked> Sakelar tertutup</label><canvas id="circuitCanvas" aria-label="Diagram rangkaian baterai dan resistor"></canvas>'+out();function update(){const v=Number(val('voltage')),r=Number(val('resistance')),closed=$s('#closedCircuit').checked;const valid=Number.isFinite(v)&&r>0;const i=valid&&closed?v/r:0;$s('#studyResult').textContent=valid?'I = V/R = '+fmt(i)+' A · P = V × I = '+fmt(v*i)+' W'+(!closed?' · Sakelar terbuka.':''):'Hambatan harus lebih dari nol.';const canvas=$s('#circuitCanvas'),w=canvas.clientWidth;canvas.width=w;canvas.height=300;const c=canvas.getContext('2d');c.strokeStyle=closed?'#739bff':'#69748a';c.lineWidth=3;c.strokeRect(45,65,w-90,155);c.clearRect(35,118,20,50);c.beginPath();c.moveTo(25,133);c.lineTo(65,133);c.moveTo(33,151);c.lineTo(57,151);c.stroke();c.clearRect(w/2-36,55,72,20);c.strokeRect(w/2-36,54,72,23);c.clearRect(w-57,130,24,40);c.beginPath();c.moveTo(w-45,130);c.lineTo(closed?w-45:w-65,170);c.stroke();c.fillStyle='#d7e7ff';c.font='16px system-ui';c.fillText('V',16,108);c.fillText('R',w/2-6,42);}['voltage','resistance','closedCircuit'].forEach(i=>on(i,update,'input'));update();}
 if(id==='density'){target.innerHTML='<h3>Tenggelam atau terapung?</h3>'+input('Massa benda (g)','objectMass','50','number')+input('Volume benda (cm³)','objectVolume','100','number')+input('Massa jenis cairan (g/cm³)','fluidDensity','1','number')+'<div class="study-lab-visual" style="background:linear-gradient(transparent 20%,#173e68 20%)"><div id="densityObject" style="border:2px solid #a9c6ff;background:#6d92dd;width:65px;height:50px;transition:transform .3s"></div></div>'+out();function update(){const m=Number(val('objectMass')),v=Number(val('objectVolume')),f=Number(val('fluidDensity'));if(m<=0||v<=0||f<=0){$s('#studyResult').textContent='Semua nilai harus lebih dari nol.';return;}const d=m/v;$s('#densityObject').style.transform='translateY('+(d>f?45:d<f?-35:0)+'px)';$s('#studyResult').textContent='ρ = m/V = '+fmt(d)+' g/cm³. Benda '+(Math.abs(d-f)<1e-9?'melayang':d<f?'terapung':'tenggelam')+' karena massa jenisnya '+(Math.abs(d-f)<1e-9?'sama dengan':d<f?'lebih kecil daripada':'lebih besar daripada')+' cairan.';}['objectMass','objectVolume','fluidDensity'].forEach(i=>on(i,update,'input'));update();}
 if(id==='particles'){target.innerHTML='<h3>Model partikel</h3><label for="particleState">Wujud zat</label><select id="particleState"><option value="solid">Padat</option><option value="liquid">Cair</option><option value="gas">Gas</option></select><label for="particleEnergy">Energi gerak relatif</label><input id="particleEnergy" class="study-slider" type="range" min="1" max="10" value="4"><canvas id="particleCanvas" aria-label="Diagram gerak partikel"></canvas><div class="study-output" id="particleInfo"></div>';const canvas=$s('#particleCanvas');let frame;const points=Array.from({length:35},()=>({x:Math.random(),y:Math.random(),vx:(Math.random()-.5)*.004,vy:(Math.random()-.5)*.004}));function draw(){if(canvas.hidden)return;const w=canvas.clientWidth;canvas.width=w;canvas.height=300;const c=canvas.getContext('2d'),mode=val('particleState'),energy=Number(val('particleEnergy'));$s('#particleInfo').textContent=mode==='solid'?'Padat: partikel bergetar di sekitar posisi tetap.':mode==='liquid'?'Cair: partikel tetap berdekatan tetapi dapat bergerak melewati satu sama lain.':'Gas: partikel bergerak bebas dan mengisi ruang. Model kualitatif, bukan skala molekul sebenarnya.';points.forEach((p,i)=>{let x,y;if(mode==='solid'){x=w/2-72+(i%7)*24+Math.sin(performance.now()*.004+i)*energy*.4;y=100+Math.floor(i/7)*24;}else{p.x+=p.vx*energy*.3;p.y+=p.vy*energy*.3;if(p.x<0||p.x>1){p.vx*=-1;p.x=Math.max(0,Math.min(1,p.x));}if(p.y<0||p.y>1){p.vy*=-1;p.y=Math.max(0,Math.min(1,p.y));}x=12+p.x*(w-24);y=mode==='liquid'?160+p.y*120:12+p.y*276;}c.fillStyle='#87b0ff';c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.fill();});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)frame=requestAnimationFrame(draw);}['particleState','particleEnergy'].forEach(id=>on(id,()=>{cancelAnimationFrame(frame);draw();},'input'));draw();labCleanup=()=>cancelAnimationFrame(frame);}
 window.dispatchEvent(new CustomEvent('lab-experiment-change',{detail:{id}}));target.insertAdjacentHTML('beforeend','<div class="study-row">'+button('Jelaskan eksperimen ini','labAsk')+'</div>');on('labAsk',()=>ask('Jelaskan eksperimen '+experiments.find(e=>e[0]===id)[1]+' dan buat satu pertanyaan pemahaman untuk siswa SMP.'));
}
body.querySelectorAll('[data-experiment]').forEach(b=>b.onclick=()=>select(b.dataset.experiment));select('ph');cleanup=()=>labCleanup();};
const formulas=[['Luas persegi','A = s²','s: panjang sisi.'],['Keliling persegi','K = 4s','s: panjang sisi.'],['Luas persegi panjang','A = p × l','p: panjang; l: lebar.'],['Keliling persegi panjang','K = 2(p + l)','p: panjang; l: lebar.'],['Luas segitiga','A = ½ × a × t','a: alas; t: tinggi tegak lurus.'],['Luas jajar genjang','A = a × t','a: alas; t: tinggi.'],['Luas trapesium','A = ½(a + b)t','a dan b: sisi sejajar; t: tinggi.'],['Luas belah ketupat','A = ½d₁d₂','d₁, d₂: diagonal.'],['Luas layang-layang','A = ½d₁d₂','d₁, d₂: diagonal.'],['Luas lingkaran','A = πr²','r: jari-jari.'],['Keliling lingkaran','K = 2πr','r: jari-jari.'],['Pythagoras','c² = a² + b²','Segitiga siku-siku; c: sisi miring.'],['Sudut dalam poligon','Jumlah = (n − 2) × 180°','n: jumlah sisi.'],['Sudut luar poligon beraturan','θ = 360°/n','n: jumlah sisi.'],['Volume kubus','V = s³','s: panjang sisi.'],['Luas permukaan kubus','A = 6s²','s: panjang sisi.'],['Volume balok','V = p × l × t','p, l, t: dimensi balok.'],['Luas permukaan balok','A = 2(pl + pt + lt)','p, l, t: dimensi balok.'],['Volume prisma','V = luas alas × tinggi','Tinggi tegak lurus alas.'],['Volume tabung','V = πr²t','r: jari-jari; t: tinggi.'],['Luas permukaan tabung','A = 2πr(r + t)','Termasuk kedua alas.'],['Volume kerucut','V = ⅓πr²t','t: tinggi tegak lurus.'],['Volume limas','V = ⅓ × luas alas × tinggi','Tinggi tegak lurus alas.'],['Volume bola','V = ⁴⁄₃πr³','r: jari-jari.'],['Luas permukaan bola','A = 4πr²','r: jari-jari.'],['Gradien garis','m = (y₂ − y₁)/(x₂ − x₁)','Untuk x₂ ≠ x₁.'],['Persamaan garis','y = mx + c','m: gradien; c: intersep y.'],['Rata-rata','x̄ = jumlah nilai / banyak nilai','Semua nilai memiliki bobot sama.'],['Peluang','P(A) = hasil mendukung / semua hasil','Hasil-hasil harus sama mungkin.'],['Persentase perubahan','Δ% = (baru − lama)/lama × 100%','Nilai lama tidak nol.'],['Bunga sederhana','I = P × r × t','r: suku bunga desimal per periode; t: periode.'],['Kecepatan rata-rata','v = jarak / waktu','Jarak total dibagi waktu total.'],['Percepatan','a = Δv / Δt','Perubahan kecepatan per waktu.'],['Gaya','F = ma','m: massa; a: percepatan.'],['Berat','W = mg','g: percepatan gravitasi.'],['Massa jenis','ρ = m/V','m: massa; V: volume.'],['Tekanan','p = F/A','Gaya tegak lurus per luas.'],['Usaha','W = Fd','Gaya konstan sejajar perpindahan.'],['Energi kinetik','Eₖ = ½mv²','m: massa; v: kelajuan.'],['Energi potensial gravitasi','Eₚ = mgh','Dekat permukaan dengan g konstan.'],['Daya','P = E/t','Energi per waktu.'],['Hukum Ohm','V = IR','Resistor ohmik pada kondisi tetap.'],['Periode bandul','T = 2π√(L/g)','Sudut kecil, gesekan diabaikan.']];
renderers.formulas=()=>{body.innerHTML='<h3>Hitung bangun</h3><label for="shape">Bangun</label><select id="shape"><option value="square">Persegi</option><option value="rectangle">Persegi panjang</option><option value="triangle">Segitiga</option><option value="circle">Lingkaran</option><option value="cube">Kubus</option><option value="cuboid">Balok</option><option value="cylinder">Tabung</option><option value="sphere">Bola</option></select><div id="shapeInputs"></div>'+out()+input('Cari rumus','formulaSearch')+'<div id="formulaList" class="study-formulas"></div>';function list(){const q=val('formulaSearch').toLowerCase();$s('#formulaList').innerHTML=formulas.filter(f=>f.join(' ').toLowerCase().includes(q)).map(f=>`<details><summary>${f[0]}</summary><p><strong>${f[1]}</strong><br>${f[2]}</p></details>`).join('')||'<p>Tidak ada rumus yang cocok.</p>';}function shape(){const type=val('shape'),labels={square:['Sisi'],rectangle:['Panjang','Lebar'],triangle:['Alas','Tinggi'],circle:['Jari-jari'],cube:['Sisi'],cuboid:['Panjang','Lebar','Tinggi'],cylinder:['Jari-jari','Tinggi'],sphere:['Jari-jari']}[type];$s('#shapeInputs').innerHTML='<p class="study-muted">Gunakan satuan panjang yang sama. Hasil luas dalam satuan², volume dalam satuan³.</p>'+labels.map((l,i)=>input(l,'shape'+i,'5','number')).join('')+button('Hitung','solveShape',true);on('solveShape',()=>{const [a,b,c]=labels.map((_,i)=>Number(val('shape'+i)));if(labels.some((_,i)=>!Number.isFinite(Number(val('shape'+i)))||Number(val('shape'+i))<=0)){$s('#studyResult').textContent='Masukkan dimensi positif.';return;}const result=type==='square'?'Luas = '+fmt(a*a)+' satuan²; keliling = '+fmt(4*a)+' satuan.':type==='rectangle'?'Luas = '+fmt(a*b)+' satuan²; keliling = '+fmt(2*(a+b))+' satuan.':type==='triangle'?'Luas = '+fmt(a*b/2)+' satuan².':type==='circle'?'Luas = '+fmt(Math.PI*a*a)+' satuan²; keliling = '+fmt(2*Math.PI*a)+' satuan.':type==='cube'?'Volume = '+fmt(a**3)+' satuan³; luas permukaan = '+fmt(6*a*a)+' satuan².':type==='cuboid'?'Volume = '+fmt(a*b*c)+' satuan³; luas permukaan = '+fmt(2*(a*b+a*c+b*c))+' satuan².':type==='cylinder'?'Volume = '+fmt(Math.PI*a*a*b)+' satuan³; luas permukaan = '+fmt(2*Math.PI*a*(a+b))+' satuan².':'Volume = '+fmt(4/3*Math.PI*a**3)+' satuan³; luas permukaan = '+fmt(4*Math.PI*a*a)+' satuan².';$s('#studyResult').textContent=result;});$s('#solveShape').click();}on('shape',shape,'change');on('formulaSearch',list,'input');shape();list();};
let cardIndex=0,cardBack=false,deckIndex=0;
renderers.cards=()=>{if(!state.decks.length)state.decks.push({name:'Contoh IPA',cards:[['Apa fungsi inti sel?','Mengandung materi genetik dan mengatur aktivitas sel.'],['Apa fungsi kloroplas?','Tempat fotosintesis pada sel tumbuhan.'],['Apa fungsi membran sel?','Mengatur perpindahan zat masuk dan keluar sel.']]});deckIndex=Math.min(deckIndex,state.decks.length-1);const deck=state.decks[deckIndex];cardIndex=Math.min(cardIndex,Math.max(0,deck.cards.length-1));body.innerHTML='<label for="deckSelect">Deck</label><select id="deckSelect">'+state.decks.map((d,i)=>`<option value="${i}" ${i===deckIndex?'selected':''}>${esc(d.name)}</option>`).join('')+'</select><p class="study-muted" id="cardProgress"></p><button id="flashCard" class="study-flip" aria-label="Balik flashcard"></button><div class="study-row">'+button('Sebelumnya','cardPrev')+button('Balik kartu','cardFlip',true)+button('Berikutnya','cardNext')+'</div><div class="study-card"><h3>Buat deck</h3>'+input('Nama deck','deckName')+'<label for="deckText">Satu kartu per baris: pertanyaan | jawaban</label><textarea id="deckText" placeholder="Ibu kota Indonesia? | Jakarta"></textarea><div class="study-row">'+button('Simpan deck','saveDeck',true)+button('Buat dengan AI','aiDeck')+'</div></div>';function show(){const c=deck.cards[cardIndex];$s('#cardProgress').textContent=`${cardIndex+1} / ${deck.cards.length} · ${cardBack?'Jawaban':'Pertanyaan'}`;$s('#flashCard').textContent=c?.[cardBack?1:0]||'Deck ini kosong.';}function flip(){cardBack=!cardBack;show();}on('flashCard',flip);on('cardFlip',flip);on('cardNext',()=>{cardIndex=(cardIndex+1)%deck.cards.length;cardBack=false;show();});on('cardPrev',()=>{cardIndex=(cardIndex+deck.cards.length-1)%deck.cards.length;cardBack=false;show();});on('deckSelect',()=>{deckIndex=Number(val('deckSelect'));cardIndex=0;cardBack=false;renderers.cards();});on('saveDeck',()=>{const cards=val('deckText').split('\n').filter(l=>l.trim()).map(l=>{const i=l.indexOf('|');return i>0?[l.slice(0,i).trim(),l.slice(i+1).trim()]:null;});if(!val('deckName').trim()||!cards.length||cards.some(c=>!c||!c[1]))return showToast('Isi nama dan kartu dalam format pertanyaan | jawaban.');state.decks.push({name:val('deckName').trim().slice(0,100),cards:cards.slice(0,200)});persist();deckIndex=state.decks.length-1;cardIndex=0;cardBack=false;renderers.cards();});on('aiDeck',()=>ask('Buat 10 flashcard tentang '+(val('deckName').trim()||'[tulis topik]')+'. Sertakan satu blok kode ```flashcards berisi JSON: {"title":"Nama deck","cards":[{"front":"Pertanyaan","back":"Jawaban"}]}.'));show();};
window.receiveStudyCards=text=>{const block=String(text).match(/```flashcards\s*\n([\s\S]*?)```/i);if(!block)return;try{const data=JSON.parse(block[1]);const cards=(data.cards||[]).slice(0,200).filter(c=>typeof c.front==='string'&&typeof c.back==='string'&&c.front.trim()&&c.back.trim()).map(c=>[c.front.slice(0,2000),c.back.slice(0,4000)]);if(!cards.length)return;state.decks.push({name:String(data.title||'Deck AI').slice(0,100),cards});persist();showToast('Flashcard AI disimpan ke Alat belajar.');if(current==='cards'&&panel.classList.contains('open'))renderers.cards();}catch{}};
let timer={end:0,remaining:25*60,running:false,phase:'Fokus',completed:false};
function seconds(){return timer.running?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining;}
function tick(){const n=seconds();if(timer.running&&n===0){timer.running=false;timer.remaining=0;timer.completed=true;showToast(timer.phase+' selesai.');}if(current==='timer'&&panel.classList.contains('open')){const el=$s('#timerDisplay');if(el)el.textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');const b=$s('#timerToggle');if(b)b.textContent=timer.running?'Jeda':'Mulai';}const launcher=$s('#studyTopLaunch');launcher.textContent=timer.running?timer.phase+' '+Math.floor(n/60)+':'+String(n%60).padStart(2,'0'):'Alat belajar';}
setInterval(tick,500);
renderers.timer=()=>{body.innerHTML='<div class="study-tabs">'+['Fokus','Istirahat pendek','Istirahat panjang'].map((p,i)=>`<button class="study-button" data-phase="${i}">${p}</button>`).join('')+'</div>'+input('Durasi (menit)','timerMinutes',timer.phase==='Fokus'?25:timer.phase==='Istirahat pendek'?5:15,'number')+'<div class="study-timer" id="timerDisplay" role="timer" aria-label="Sisa waktu"></div><p class="study-muted" id="timerPhase">'+timer.phase+'</p><div class="study-row">'+button('Mulai','timerToggle',true)+button('Reset','timerReset')+'</div><p class="study-muted">Tetap berjalan saat panel ditutup selama halaman ini terbuka. Timer memakai waktu sebenarnya, termasuk ketika tab berada di latar belakang.</p>';function reset(){const n=Number(val('timerMinutes'));if(n<1||n>180)return showToast('Pilih durasi 1–180 menit.');timer.running=false;timer.completed=false;timer.remaining=Math.round(n*60);tick();}on('timerToggle',()=>{if(timer.running){timer.remaining=seconds();timer.running=false;}else{if(timer.completed||!timer.remaining)reset();timer.end=Date.now()+timer.remaining*1000;timer.running=true;}tick();});on('timerReset',reset);body.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{const i=+b.dataset.phase;timer.phase=['Fokus','Istirahat pendek','Istirahat panjang'][i];$s('#timerMinutes').value=[25,5,15][i];$s('#timerPhase').textContent=timer.phase;reset();});on('timerMinutes',reset,'change');tick();};
function today(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
renderers.planner=()=>{body.innerHTML=input('Nama tugas','taskName')+input('Mata pelajaran','taskSubject')+input('Tenggat','taskDate',today(),'date')+'<div class="study-row">'+button('Tambahkan tugas','addTask',true)+'</div><div id="taskList"></div><p class="study-muted">Tersimpan di perangkat ini untuk akunmu.</p>';function list(){const sorted=state.tasks.map((t,i)=>({...t,index:i})).sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));$s('#taskList').innerHTML=sorted.map(t=>`<div class="study-task ${t.done?'done':t.date<today()?'overdue':''}"><input type="checkbox" id="taskCheck${t.index}" data-task="${t.index}" ${t.done?'checked':''} aria-label="Selesai: ${esc(t.name)}"><label for="taskCheck${t.index}">${esc(t.name)}<small>${esc(t.subject)} · ${esc(t.date)}${!t.done&&t.date<today()?' · Terlewat':''}</small></label><button class="study-button" data-remove-task="${t.index}" aria-label="Hapus ${esc(t.name)}">×</button></div>`).join('')||'<div class="study-empty">Belum ada tugas. Tambahkan tugas pertamamu.</div>';body.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{state.tasks[+b.dataset.task].done=b.checked;persist();list();});body.querySelectorAll('[data-remove-task]').forEach(b=>b.onclick=()=>{if(!confirm('Hapus tugas ini dari agenda perangkat?'))return;state.tasks.splice(+b.dataset.removeTask,1);persist();list();});}on('addTask',()=>{if(!val('taskName').trim()||!val('taskDate'))return showToast('Isi nama tugas dan tenggat.');state.tasks.push({name:val('taskName').trim().slice(0,200),subject:val('taskSubject').trim().slice(0,100),date:val('taskDate'),done:false});persist();$s('#taskName').value='';list();});list();};
let noteIndex=0;
renderers.notes=()=>{if(!state.notes.length){state.notes.push({title:'Catatan pertama',text:''});persist();}noteIndex=Math.min(noteIndex,state.notes.length-1);const note=state.notes[noteIndex];body.innerHTML='<label for="noteSelect">Catatan</label><select id="noteSelect">'+state.notes.map((n,i)=>`<option value="${i}" ${i===noteIndex?'selected':''}>${esc(n.title)}</option>`).join('')+'</select>'+input('Judul','noteTitle',note.title)+'<label for="noteText">Isi catatan</label><textarea id="noteText" style="min-height:240px">'+esc(note.text)+'</textarea><p class="study-mini-status" id="noteStatus">Tersimpan di perangkat ini</p><div class="study-row">'+button('Catatan baru','newNote')+button('Unduh .txt','downloadNote')+'</div><div class="study-row">'+button('Ringkas dengan AI','summarizeNote')+button('Kuis dari catatan','quizNote')+'</div>';function save(){note.title=val('noteTitle').trim()||'Tanpa judul';note.text=val('noteText');persist();$s('#noteSelect').options[noteIndex].textContent=note.title;$s('#noteStatus').textContent='Tersimpan di perangkat ini';}on('noteTitle',save,'input');on('noteText',save,'input');on('noteSelect',()=>{noteIndex=+val('noteSelect');renderers.notes();});on('newNote',()=>{state.notes.push({title:'Catatan '+(state.notes.length+1),text:''});persist();noteIndex=state.notes.length-1;renderers.notes();});on('downloadNote',()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([note.title+'\n\n'+note.text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='catatan-7mit.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});on('summarizeNote',()=>{if(!note.text.trim())return showToast('Tulis catatan terlebih dahulu.');ask('Ringkas catatan berikut menjadi poin belajar:\n\n'+note.text.slice(0,10000));});on('quizNote',()=>{if(!note.text.trim())return showToast('Tulis catatan terlebih dahulu.');ask('Buat kuis interaktif 10 pertanyaan dari catatan berikut:\n\n'+note.text.slice(0,10000));});};
