function quizQuestions(subject){if(subject==='Matematika')return Array.from({length:10},(_,i)=>{const a=3+Math.floor(Math.random()*17),b=2+Math.floor(Math.random()*9),n=i%5;const q=n===0?`${a} × ${b} = ?`:n===1?`x + ${b} = ${a+b}. x = ?`:n===2?`Luas persegi dengan sisi ${b} cm?`:n===3?`Keliling persegi panjang ${a} cm × ${b} cm?`:`${b*10}% dari ${a*10} = ?`,ans=n===0?a*b:n===1?a:n===2?b*b:n===3?2*(a+b):a*b;return {question:q,options:[String(ans),String(ans+1),String(ans+2),String(ans+3)],answer:0,explanation:n===0?'Kalikan kedua bilangan.':n===1?'Kurangi kedua sisi dengan '+b+'.':n===2?'Luas persegi = sisi × sisi.':n===3?'Keliling = 2 × (panjang + lebar).':'Persentase dibagi 100 lalu dikalikan nilai awal.'};});return (banks[subject]||banks.IPA).map(q=>({question:q[0],options:q[1],answer:q[2],explanation:q[3]}));}
let quizState=null;
renderers.quiz=()=>{body.innerHTML='<label for="quizSubject">Mata pelajaran</label><select id="quizSubject">'+['Matematika','IPA','Inggris','Indonesia','Geografi'].map(s=>`<option>${s}</option>`).join('')+'</select><div class="study-row">'+button('Mulai 10 soal','startQuiz',true)+'</div><div id="arena"></div><div class="study-card"><h3>Topik khusus dengan AI</h3>'+input('Topik','quizTopic')+button('Buat kuis AI','customQuiz')+'</div>';on('startQuiz',()=>{const questions=quizQuestions(val('quizSubject')).sort(()=>Math.random()-.5).map(q=>{const correct=q.options[q.answer],options=[...q.options];for(let i=options.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[options[i],options[j]]=[options[j],options[i]];}return {...q,options,answer:options.indexOf(correct)};});quizState={questions,index:0,score:0,answered:false};question();});on('customQuiz',()=>{if(!val('quizTopic').trim())return showToast('Tulis topik kuis.');ask('Buat kuis interaktif 10 pertanyaan pilihan ganda tentang '+val('quizTopic')+'. Sertakan penjelasan setiap jawaban.');});if(quizState){if(quizState.answered){quizState.index++;quizState.answered=false;}question();}
function question(){const a=$s('#arena');if(!a)return;const s=quizState;if(s.index>=s.questions.length){a.innerHTML='<div class="study-output"><strong>Skor '+s.score+' / '+s.questions.length+'</strong><p>Latihan selesai. Pilih Mulai 10 soal untuk mencoba lagi.</p></div>';return;}const q=s.questions[s.index];s.answered=false;a.innerHTML='<div class="study-card"><p class="study-muted">Soal '+(s.index+1)+' / '+s.questions.length+'</p><h3>'+esc(q.question)+'</h3>'+q.options.map((o,i)=>`<button class="study-button" style="display:block;width:100%;margin:8px 0;text-align:left" data-arena-answer="${i}" ${s.answered?'disabled':''}>${esc(o)}</button>`).join('')+'<div id="arenaFeedback" role="status"></div></div>';a.querySelectorAll('[data-arena-answer]').forEach(b=>b.onclick=()=>{if(s.answered)return;s.answered=true;const correct=+b.dataset.arenaAnswer===q.answer;if(correct)s.score++;a.querySelectorAll('[data-arena-answer]').forEach(b=>b.disabled=true);$s('#arenaFeedback').innerHTML='<p>'+(correct?'Benar!':'Belum tepat. Jawaban: '+esc(q.options[q.answer]))+'</p><p>'+esc(q.explanation)+'</p>'+button('Lanjut','nextArena',true);on('nextArena',()=>{s.index++;s.answered=false;question();});});}
};
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
const mic=$s('#voiceInput');if(!Recognition){mic.disabled=true;mic.title='Dikte belum tersedia di browser ini.';}else{let recognizer=null;mic.onclick=()=>{if(recognizer){recognizer.stop();return;}const r=new Recognition();recognizer=r;r.lang=language==='en'?'en-US':'id-ID';r.interimResults=true;const initial=els.input.value;r.onresult=e=>{const text=Array.from(e.results).map(row=>row[0].transcript).join(' ');els.input.value=(initial?initial+' ':'')+text;autoResize();};r.onstart=()=>{mic.setAttribute('aria-pressed','true');showToast('Mendengarkan. Klik mikrofon lagi untuk berhenti.');};r.onend=()=>{recognizer=null;mic.setAttribute('aria-pressed','false');};r.onerror=e=>{showToast(e.error==='not-allowed'?'Izin mikrofon belum diberikan.':'Dikte berhenti. Silakan coba lagi.');};try{r.start();}catch{recognizer=null;showToast('Dikte belum bisa dimulai.');}};}
